// 42-tap direct-form FIR, 8-bit samples, unpipelined MAC cone (the long
// register-to-register path -> lower Fmax; pipeline it to go faster).
module firr42_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:41];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd1 * xs[0] + 8'd6 * xs[1] + 8'd15 * xs[2] + 8'd28 * xs[3] + 8'd45 * xs[4] + 8'd66 * xs[5] + 8'd90 * xs[6] + 8'd117 * xs[7] + 8'd147 * xs[8] + 8'd180 * xs[9] + 8'd216 * xs[10] + 8'd255 * xs[11] + 8'd297 * xs[12] + 8'd342 * xs[13] + 8'd390 * xs[14] + 8'd441 * xs[15] + 8'd495 * xs[16] + 8'd552 * xs[17] + 8'd612 * xs[18] + 8'd675 * xs[19] + 8'd741 * xs[20] + 8'd810 * xs[21] + 8'd882 * xs[22] + 8'd957 * xs[23] + 8'd1035 * xs[24] + 8'd1116 * xs[25] + 8'd1200 * xs[26] + 8'd1287 * xs[27] + 8'd1377 * xs[28] + 8'd1470 * xs[29] + 8'd1566 * xs[30] + 8'd1665 * xs[31] + 8'd1767 * xs[32] + 8'd1872 * xs[33] + 8'd1980 * xs[34] + 8'd2091 * xs[35] + 8'd2205 * xs[36] + 8'd2322 * xs[37] + 8'd2442 * xs[38] + 8'd2565 * xs[39] + 8'd2691 * xs[40] + 8'd2820 * xs[41];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 42; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 42; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
